def _canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _parse_datetime(value: Any) -> datetime:
    text = str(value or "").strip()
    if not text:
        raise ValueError("timestamp is missing")
    parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        raise ValueError(f"timestamp has no timezone: {text}")
    return parsed.astimezone(timezone.utc)


def _cover_evidence(value: Any) -> dict[str, Any]:
    text = value if isinstance(value, str) else ""
    if not text.startswith("data:") or ";base64," not in text:
        return {"mime": "", "sha256": "", "bytes": 0, "valid_data_url": False}
    header, encoded = text.split(",", 1)
    mime = header[5:].split(";", 1)[0]
    try:
        payload = base64.b64decode(encoded, validate=True)
    except Exception:
        return {"mime": mime, "sha256": "", "bytes": 0, "valid_data_url": False}
    return {
        "mime": mime,
        "sha256": hashlib.sha256(payload).hexdigest(),
        "bytes": len(payload),
        "valid_data_url": True,
    }


def _note_evidence(note: Mapping[str, Any] | None) -> dict[str, Any]:
    row = note or {}
    return {
        "id": row.get("id"),
        "authorHandle": row.get("authorHandle"),
        "title": row.get("title"),
        "text": row.get("text"),
        "category": row.get("category"),
        "tags": row.get("tags"),
        "location": row.get("location"),
        "cover": _cover_evidence(row.get("cover")),
    }


def _event_payload(event: Mapping[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in event.items() if key not in {"seq", "timestamp"}}


def _failure(actual: Any, expected: Any) -> str | None:
    return None if actual == expected else "exact value, cardinality, or causal-order contract mismatch"


def _note_predicate(raw: Mapping[str, Any], group: str) -> tuple[bool, Any, Any, str | None]:
    groups = raw.get("groups") if isinstance(raw.get("groups"), Mapping) else {}
    actual = groups.get(group) if isinstance(groups.get(group), Mapping) else {}
    actual_note = actual.get("note") if isinstance(actual.get("note"), Mapping) else {}
    expected = {
        "match_count": 1,
        "note": _NOTE_EXPECTED[group],
        "application_build": EXPECTED_BUILD,
    }
    projected = {
        "match_count": actual.get("match_count"),
        "note": {key: actual_note.get(key) for key in _NOTE_EXPECTED[group]},
        "application_build": actual.get("application_build"),
    }
    passed = projected == expected and isinstance(actual_note.get("id"), str) and bool(actual_note.get("id"))
    return passed, expected, actual, _failure(projected, expected)


