# Browsing is not a business action and is never counted (this also makes the
# launch-time home feed_view irrelevant to where the baseline falls).
_BROWSING_EVENT_TYPES = frozenset({"feed_view", "note_detail_opened"})
# Saving an unchanged profile again leaves the same state; it counts once.
_REPEATABLE_LABELS = frozenset({"profile_updated"})
# "Create and publish three new notes, interact with an existing post, and update
# the user profile" states no order; the engaged note is seeded.
REQUIRED_EVENT_ORDER: tuple[tuple[str, str], ...] = ()


def _is_business_event(event_type: str) -> bool:
    return event_type not in _BROWSING_EVENT_TYPES and not event_type.startswith("session_")


def _expected_business_events(raw: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    groups = raw.get("groups") if isinstance(raw.get("groups"), Mapping) else {}
    ids = {
        name: ((groups.get(name) or {}).get("note") or {}).get("id")
        for name in ("arrival_note", "forum_plan_note", "group_session_note")
    }
    return {
        "arrival_note_created": {"type": "note_created", "noteId": ids["arrival_note"], "title": "Forum Arrival Outfit", "category": "Fashion", "tags": ["forum", "trip", "outfit"]},
        "cold_brew_like": {"type": "note_like_toggled", "noteId": "n-3057", "authorHandle": "lina", "active": True},
        "cold_brew_save": {"type": "note_save_toggled", "noteId": "n-3057", "authorHandle": "lina", "active": True},
        "profile_updated": {"type": "profile_updated", "displayName": "Lina Park", "title": "City life editor", "bio": "Collecting honest routes, useful details, and everyday ideas worth trying. Forum travel editor"},
        "forum_plan_note_created": {"type": "note_created", "noteId": ids["forum_plan_note"], "title": "Two Day Forum Plan", "category": "Fashion", "tags": ["forum", "plan", "attire"]},
        "group_session_note_created": {"type": "note_created", "noteId": ids["group_session_note"], "title": "Group Session Outfit", "category": "Fashion", "tags": ["forum", "session", "attire"]},
    }


def _business_projection(
    events: Any, expected: Mapping[str, Mapping[str, Any]]
) -> list[dict[str, Any]]:
    projection: list[dict[str, Any]] = []
    seen: set[str] = set()
    for event in events if isinstance(events, list) else []:
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("type") or "")
        if not _is_business_event(event_type):
            continue
        payload = _event_payload(event)
        label = next((name for name, wanted in expected.items() if payload == wanted), None)
        if label is None:
            label = f"unexpected:{event_type}:{event.get('seq')}"
        elif label in _REPEATABLE_LABELS and label in seen:
            continue
        seen.add(label)
        projection.append({"label": label, "seq": event.get("seq"), "payload": payload})
    return projection


def durable_events_and_required_order_predicate(raw: Mapping[str, Any]) -> tuple[bool, Any, Any, str | None]:
    """Each requested business event exactly once, nothing else; no order is stated."""
    expected_events = _expected_business_events(raw)
    projection = _business_projection(raw.get("event_suffix"), expected_events)
    labels = [row["label"] for row in projection]
    missing, extra = multiset_diff(list(expected_events), labels)
    violations = order_violations(labels, REQUIRED_EVENT_ORDER)
    expected = {
        "business_events": expected_events,
        "missing": [],
        "extra": [],
        "required_order": [list(pair) for pair in REQUIRED_EVENT_ORDER],
        "order_violations": [],
    }
    actual = {
        "labels": labels,
        "missing": missing,
        "extra": extra,
        "order_violations": violations,
        "projection": projection,
    }
    passed = not missing and not extra and not violations
    reason = None if passed else (
        "a requested business event is missing, an unexpected or duplicate business "
        "event was recorded, or a required order was broken"
    )
    return passed, expected, actual, reason


class OpenNoteForumOutfitThreeNotes194503Evaluator(BaseEvaluator):
    """Verify exact durable state and the requested business events without GUI actions."""

    @staticmethod
    def _collect_raw(
        state: Mapping[str, Any],
        *,
        boundary: Mapping[str, Any],
        application_build: Mapping[str, Any],
        observed_at: str,
        evaluation_session_id: str,
        udid: str,
    ) -> dict[str, Any]:
        notes = [dict(item) for item in state.get("notes", []) if isinstance(item, Mapping)]
        users = [dict(item) for item in state.get("users", []) if isinstance(item, Mapping)]
        user_state = state.get("userState") if isinstance(state.get("userState"), Mapping) else {}
        lina_state = user_state.get("lina") if isinstance(user_state.get("lina"), Mapping) else {}
        liked = set(lina_state.get("likedNoteIds") or [])
        saved = set(lina_state.get("savedNoteIds") or [])

        groups: dict[str, Any] = {}
        for group, expected in _NOTE_EXPECTED.items():
            matches = [
                note for note in notes
                if note.get("title") == expected["title"] and note.get("authorHandle") == "lina"
            ]
            groups[group] = {
                "match_count": len(matches),
                "note": _note_evidence(matches[0] if len(matches) == 1 else None),
                "application_build": dict(application_build),
            }

        target_matches = [
            note for note in notes
            if note.get("id") == "n-3057"
            and note.get("title") == "Monday cold brew walk with half-hour line"
        ]
        target = target_matches[0] if len(target_matches) == 1 else {}
        groups["cold_brew_engagement"] = {
            "match_count": len(target_matches),
            "target_note": {
                "id": target.get("id"),
                "authorHandle": target.get("authorHandle"),
                "title": target.get("title"),
                "category": target.get("category"),
                "liked": "n-3057" in liked,
                "saved": "n-3057" in saved,
            },
        }

        lina_matches = [user for user in users if user.get("handle") == "lina"]
        lina = lina_matches[0] if len(lina_matches) == 1 else {}
        groups["profile_bio"] = {
            "match_count": len(lina_matches),
            "profile": {"handle": lina.get("handle"), "bio": lina.get("bio")},
        }

        events = [dict(item) for item in state.get("evaluationEvents", []) if isinstance(item, Mapping)]
        if boundary.get("mode") == "automatic_baseline_seq":
            floor = int(boundary["baseline_max_event_seq"])
            suffix = [event for event in events if isinstance(event.get("seq"), int) and event["seq"] > floor]
            source_state_mode = "fresh_clone_verified"
        else:
            start = _parse_datetime(boundary.get("start"))
            end = _parse_datetime(boundary.get("end"))
            suffix = []
            for event in events:
                try:
                    stamp = _parse_datetime(event.get("timestamp"))
                except ValueError:
                    continue
                if start <= stamp <= end:
                    suffix.append(event)
            source_state_mode = "human_completed_eval_only"
        suffix.sort(key=lambda event: int(event.get("seq") or 0))
        return {
            "schema_version": "1.0",
            "task_id": TASK_ID,
            "evaluation_session_id": evaluation_session_id,
            "observed_at": observed_at,
            "source_state_mode": source_state_mode,
            "runtime": {
                "udid": udid,
                "ios_device_profile": IOS_DEVICE_PROFILE,
                "source_simulator_name": SOURCE_SIMULATOR_NAME,
                "bundle_id": DEFAULT_BUNDLE_ID,
                "local_state_key": LOCAL_STATE_KEY,
            },
            "boundary": dict(boundary),
            "groups": groups,
            "event_suffix": suffix,
            "state_summary": {
                "evaluationEventSeq": state.get("evaluationEventSeq"),
                "note_count": len(notes),
            },
            "read_only": True,
        }

    @staticmethod
    def _checkpoint(
        spec: Mapping[str, Any],
        outcome: tuple[bool, Any, Any, str | None],
        *,
        evidence_source: str,
        evidence_sha256: str,
        observed_at: str,
        session_id: str,
    ) -> dict[str, Any]:
        passed, expected, actual, reason = outcome
        return {
            "name": spec["name"],
            "steps": list(spec["steps"]),
            "predicate": spec["predicate"],
            "value_contract_id": spec["value_contract_id"],
            "match_mode": spec["match_mode"],
            "diagnostic": False,
            "passed": bool(passed),
            "expected": expected,
            "actual": actual,
            "ruleset_sha256": RULESET_SHA256,
            "evidence": {
                "source": evidence_source,
                "path": (
                    "$.event_suffix"
                    if spec["name"] == "durable_events_and_required_order"
                    else "$.groups"
                ),
            },
            "execution": {
                "executed": True,
                "session_id": session_id,
                "observed_at": observed_at,
                "evidence_source_sha256": evidence_sha256,
            },
            "failure_reason": None if passed else reason,
        }

    @classmethod
    def evaluate_evidence(
        cls,
        raw: Mapping[str, Any],
        *,
        evidence_source: str = "memory://opennote-evidence",
        evidence_sha256: str | None = None,
    ) -> EvalResult:
        digest = evidence_sha256 or hashlib.sha256(_canonical_bytes(raw)).hexdigest()
        outcomes = (
            arrival_note_exact_predicate(raw),
            cold_brew_engagement_exact_predicate(raw),
            profile_bio_exact_predicate(raw),
            forum_plan_note_exact_predicate(raw),
            group_session_note_exact_predicate(raw),
            durable_events_and_required_order_predicate(raw),
        )
        checks = [
            cls._checkpoint(
                spec,
                outcome,
                evidence_source=evidence_source,
                evidence_sha256=digest,
                observed_at=str(raw.get("observed_at") or ""),
                session_id=str(raw.get("evaluation_session_id") or ""),
            )
            for spec, outcome in zip(CHECKPOINT_SPECS, outcomes)
        ]
        # The recorded event suffix (navigation, feed totals, step order) is not part
        # of the brief; durable_events_and_required_order grades only the requested
        # business events as a multiset, and the brief states no order among them.
        failures = [check["name"] for check in checks if not check["passed"]]
        metadata = {
            "task_id": TASK_ID,
            "evaluator_id": EVALUATOR_ID,
            "instruction_sha256": INSTRUCTION_SHA256,
            "ruleset_sha256": RULESET_SHA256,
            "ruleset_spec": RULESET_SPEC,
            "checks": checks,
            "failures": failures,
            "read_only": True,
            "source_state_mode": raw.get("source_state_mode"),
            "raw_evidence": {"source": evidence_source, "sha256": digest},
            "current_state_summary": raw.get("state_summary"),
            "causal_boundary": raw.get("boundary"),
            "runtime": raw.get("runtime"),
            "safety": {
                "state_access": "read_only localStorage snapshot",
                "app_launch": False,
                "appium": False,
                "initializer": False,
                "gui_actions": False,
                "simulator_state_change": False,
            },
        }
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenNote exact verifier checks failed: " + ", ".join(failures),
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="All exact OpenNote durable-state, cover, build, and business-event checks passed",
            metadata=metadata,
        )

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        if (
            str(params.get("expected_instruction_sha256") or "") != INSTRUCTION_SHA256
            or str(params.get("expected_ruleset_sha256") or "") != RULESET_SHA256
        ):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="Task/evaluator digest binding mismatch",
                metadata={"read_only": True, "ruleset_sha256": RULESET_SHA256},
            )
        udid = str(params.get("udid") or "").strip()
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="OpenNote evaluator requires retained simulator UDID",
                metadata={"read_only": True, "ruleset_sha256": RULESET_SHA256},
            )
        bundle_id = str(params.get("bundle_id") or DEFAULT_BUNDLE_ID).strip()
        local_state_key = str(params.get("local_state_key") or LOCAL_STATE_KEY).strip()
        try:
            store = OpenNoteStore.from_simulator(udid, bundle_id=bundle_id, local_state_key=local_state_key)
            state = store.read_state()
            application_build, applications = self._application_identity(udid, bundle_id)
            boundary = self._resolve_boundary(context, params)
            observed_at = datetime.now().astimezone().isoformat()
            session_id = str(params.get("evaluation_session_id") or f"{TASK_ID}:{observed_at}")
            raw = self._collect_raw(
                state,
                boundary=boundary,
                application_build=application_build,
                observed_at=observed_at,
                evaluation_session_id=session_id,
                udid=udid,
            )
            evidence_path = self._evidence_output_path(context, params)
            evidence_sha256 = self._write_raw_evidence(evidence_path, raw)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read exact OpenNote evidence: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "ruleset_sha256": RULESET_SHA256,
                    "exception_type": type(exc).__name__,
                },
            )

        # Direct calls are intentional for static checkpoint coverage auditing.
        arrival_note_exact_predicate(raw)
        cold_brew_engagement_exact_predicate(raw)
        profile_bio_exact_predicate(raw)
        forum_plan_note_exact_predicate(raw)
        group_session_note_exact_predicate(raw)
        durable_events_and_required_order_predicate(raw)
        result = self.evaluate_evidence(
            raw,
            evidence_source=str(evidence_path),
            evidence_sha256=evidence_sha256,
        )
        result.metadata["observed"] = {
            "udid": udid,
            "applications": applications,
            "bundle_id": bundle_id,
            "local_state_key": local_state_key,
        }
        result.metadata["evaluator_sha256"] = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
        return result

    @staticmethod
    def _resolve_boundary(context: Mapping[str, Any], params: Mapping[str, Any]) -> dict[str, Any]:
        initialization = context.get("initialization")
        metadata = initialization.get("metadata") if isinstance(initialization, Mapping) else None
        if not isinstance(metadata, Mapping) and isinstance(initialization, Mapping):
            metadata = initialization
        baseline = metadata.get("baseline_max_event_seq") if isinstance(metadata, Mapping) else None
        if isinstance(baseline, int) and not isinstance(baseline, bool):
            return {"mode": "automatic_baseline_seq", "baseline_max_event_seq": baseline}
        start = str(params.get("manual_window_start") or MANUAL_WINDOW_START)
        end = str(params.get("manual_window_end") or MANUAL_WINDOW_END)
        if _parse_datetime(end) <= _parse_datetime(start):
            raise ValueError("manual causal window end must be later than start")
        return {"mode": "manual_recording_window", "start": start, "end": end}

    @staticmethod
    def _application_identity(udid: str, bundle_id: str) -> tuple[dict[str, str], list[dict[str, Any]]]:
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "app"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if proc.returncode != 0:
            raise RuntimeError(f"simctl get_app_container app failed: {proc.stderr.strip()}")
        from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
        app = remap_simulator_container_path(proc.stdout.strip(), udid)
        files = {
            "binary_sha256": app / "App",
            "app_js_sha256": app / "public" / "app.js",
            "local_api_js_sha256": app / "public" / "local-api.js",
        }
        observed = {key: hashlib.sha256(path.read_bytes()).hexdigest() for key, path in files.items()}
        if observed != EXPECTED_BUILD:
            raise RuntimeError(f"OpenNote application build mismatch: {observed!r}")
        return observed, [{"bundle_id": bundle_id, **observed}]

    @staticmethod
    def _evidence_output_path(context: Mapping[str, Any], params: Mapping[str, Any]) -> Path:
        explicit = str(params.get("evidence_output_path") or os.environ.get("OSOMNI_EVAL_EVIDENCE_OUTPUT") or "").strip()
        if explicit:
            return Path(explicit).expanduser().resolve()
        run_dir = str(context.get("run_dir") or "").strip()
        if not run_dir:
            location = Path(tempfile.gettempdir()) / "osomni-opennote-194503"
            location.mkdir(parents=True, exist_ok=True)
            return location / "opennote_194503_raw_evidence.json"
        return Path(run_dir).expanduser().resolve() / "opennote_194503_raw_evidence.json"

    @staticmethod
    def _write_raw_evidence(path: Path, raw: Mapping[str, Any]) -> str:
        payload = _canonical_bytes(raw) + b"\n"
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="wb",
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".tmp",
                delete=False,
            ) as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
                temporary = Path(handle.name)
            os.replace(temporary, path)
        finally:
            if temporary is not None and temporary.exists():
                temporary.unlink()
        return hashlib.sha256(path.read_bytes()).hexdigest()
